2	/**
3	 * Ochrana formularu proti CSRF (podvrzenemu pozadavku z ciziho webu).
4	 *
5	 * Kazda akce, ktera meni data:
6	 *
7	 *     // formular: hned za <form method="post">
8	 *     echo csrf_field();
9	 *
10	 *     // akce: hned po auth_require()
11	 *     if (is_post()) {
12	 *         csrf_check();
13	 *         ...
14	 *     }
15	 *
16	 * Token je jeden na session. Ulozi ho do session LegacyFrontController
17	 * a preda v $GLOBALS['LEGACY_CSRF_TOKEN']; mimo nej (cron, testy) se vygeneruje.
18	 */
19	
20	use App\Legacy\lib\AccessDenied;
21	
22	function csrf_token()
23	{
24	    if (empty($GLOBALS['LEGACY_CSRF_TOKEN']) || !is_string($GLOBALS['LEGACY_CSRF_TOKEN'])) {
25	        $GLOBALS['LEGACY_CSRF_TOKEN'] = bin2hex(random_bytes(32));
26	    }
27	
28	    return $GLOBALS['LEGACY_CSRF_TOKEN'];
29	}
30	
31	/**
32	 * Skryte pole s tokenem do kazdeho formulare s method="post".
33	 */
34	function csrf_field()
35	{
36	    return '<input type="hidden" name="_csrf" value="' . h(csrf_token()) . '">';
37	}
38	
39	/**
40	 * Overi token z POSTu. Bez platneho tokenu vyhodi AccessDenied (-> 403), nic se neulozi.
41	 */
42	function csrf_check()
43	{
44	    $sent = isset($_POST['_csrf']) ? $_POST['_csrf'] : '';
45	    if (!is_string($sent) || $sent === '' || !hash_equals(csrf_token(), $sent)) {
46	        throw new AccessDenied('Neplatný bezpečnostní token formuláře. Načtěte stránku znovu a akci opakujte.');
47	    }
48	
49	    return true;
50	}
